<?php require_once 'config.php';require_role(['admin']);$pdo=db();$msg='';if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();$act=$_POST['action']??'';if($act==='create'){$name=trim($_POST['full_name']);$u=trim($_POST['username']);$pw=$_POST['password'];$r=$_POST['role'];if(strlen($pw)<8||!in_array($r,['admin','treasurer','viewer'],true))$msg='Mot de passe de 8 caractères minimum et rôle valide requis.';else{$q=$pdo->prepare('INSERT INTO users(username,password_hash,full_name,role) VALUES(?,?,?,?)');$q->execute([$u,password_hash($pw,PASSWORD_DEFAULT),$name,$r]);audit('CREATE','users',(int)$pdo->lastInsertId(),'Création utilisateur '.$u);$msg='Utilisateur créé.';}}elseif($act==='status'){$id=(int)$_POST['id'];if($id!==(int)$_SESSION['user_id']){$q=$pdo->prepare('UPDATE users SET active=1-active WHERE id=?');$q->execute([$id]);audit('STATUS','users',$id,'Modification statut');$msg='Statut modifié.';}}elseif($act==='role'){$id=(int)$_POST['id'];$r=$_POST['role'];if(in_array($r,['admin','treasurer','viewer'],true)&&$id!==(int)$_SESSION['user_id']){$q=$pdo->prepare('UPDATE users SET role=? WHERE id=?');$q->execute([$r,$id]);audit('ROLE','users',$id,'Rôle modifié : '.$r);$msg='Permission mise à jour.';}}elseif($act==='password'){$id=(int)$_POST['id'];$pw=$_POST['password'];if(strlen($pw)>=8){$q=$pdo->prepare('UPDATE users SET password_hash=? WHERE id=?');$q->execute([password_hash($pw,PASSWORD_DEFAULT),$id]);audit('PASSWORD','users',$id,'Réinitialisation mot de passe');$msg='Mot de passe réinitialisé.';}}}$users=$pdo->query('SELECT id,username,full_name,role,active,created_at FROM users ORDER BY id')->fetchAll();$page_title='Utilisateurs et permissions';include 'partials/header.php';?><?php if($msg):?><div class="notice"><?=h($msg)?></div><?php endif?><div class="panel"><h2>Créer un utilisateur</h2><form method="post" class="form-grid"><?=csrf_field()?><input type="hidden" name="action" value="create"><div><label>Nom complet</label><input name="full_name" required></div><div><label>Identifiant</label><input name="username" required></div><div><label>Mot de passe (8 caractères minimum)</label><input type="password" name="password" minlength="8" required></div><div><label>Rôle</label><select name="role"><option value="treasurer">Trésorier — saisie et modification</option><option value="viewer">Consultation uniquement</option><option value="admin">Administrateur — tous les droits</option></select></div><div class="span-2"><button class="btn primary">Créer le compte</button></div></form></div><div class="panel"><h2>Comptes utilisateurs</h2><div class="table-wrap"><table><tr><th>Nom</th><th>Identifiant</th><th>Rôle</th><th>Statut</th><th>Actions</th></tr><?php foreach($users as $u):?><tr><td><?=h($u['full_name'])?></td><td><?=h($u['username'])?></td><td><form method="post" style="display:flex;gap:5px"><?=csrf_field()?><input type="hidden" name="action" value="role"><input type="hidden" name="id" value="<?=$u['id']?>"><select name="role"><option value="admin" <?=$u['role']==='admin'?'selected':''?>>Admin</option><option value="treasurer" <?=$u['role']==='treasurer'?'selected':''?>>Trésorier</option><option value="viewer" <?=$u['role']==='viewer'?'selected':''?>>Consultation</option></select><button class="btn">Appliquer</button></form></td><td><?=$u['active']?'Actif':'Désactivé'?></td><td><form method="post" style="display:inline"><?=csrf_field()?><input type="hidden" name="action" value="status"><input type="hidden" name="id" value="<?=$u['id']?>"><button class="btn">Activer / désactiver</button></form> <form method="post" style="display:inline"><?=csrf_field()?><input type="hidden" name="action" value="password"><input type="hidden" name="id" value="<?=$u['id']?>"><input type="password" name="password" minlength="8" placeholder="Nouveau mot de passe" required style="width:170px"><button class="btn">Réinitialiser</button></form></td></tr><?php endforeach?></table></div></div><div class="panel"><h2>Permissions</h2><p><b>Administrateur :</b> utilisateurs, sauvegarde, paramètres, opérations et clôtures.</p><p><b>Trésorier :</b> saisie, modification, consultation et rapports.</p><p><b>Consultation :</b> tableau de bord et rapports uniquement.</p></div><?php include 'partials/footer.php';?>